def find_path(graph, start, goal):
    def explore(node, path):
        # Mark the current node as visited
        path.append(node)
        if node == goal:
            # If the goal node is reached, return the full path
            return path
        # Explore all neighboring nodes
        for neighbor in graph.get(node, []):
            if neighbor not in path:
                # Recursively explore each neighbor
                result = explore(neighbor, path.copy())
                if result:
                    return result
        # If no path is found, backtrack and remove the current node
        path.pop()
        return None

    path = []
    return explore(start, path)
