    path = []
    visited = set()

    def search(node):
        if node in visited:
            return None
        if node == goal:
            return [node]
        visited.add(node)
        for neighbor in graph[node]:
            path_found = search(neighbor)
            if path_found:
                return [node] + path_found
        return None

    return search(start)
