        if node == goal:
            return True
        if node in visited:
            return False
        visited.add(node)
        path.append(node)
        for neighbor in graph.get(node, []):
            if explore(neighbor):
                return True
        path.pop()
        return False

    if explore(start):
        return path
    else:
        return None
